-- Day 8K: additive moderation and factual trust foundation. Reports are signals, never verdicts.
DO $$ BEGIN CREATE TYPE public.moderation_case_status AS ENUM ('NORMAL','LIMITED','UNDER_REVIEW','SUSPENDED','BANNED','REGULATORY_HOLD','CLOSED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
